package com.pulsesg.support.service;
import com.pulsesg.support.dto.ApiDtos.*; import com.pulsesg.support.entity.*; import com.pulsesg.support.exception.AppExceptions.*; import com.pulsesg.support.repository.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PortalService { private final UserRepository users; private final TicketRepository tickets; private final TicketMessageRepository messages; private final PasswordEncoder encoder; private final AiSuggestionService ai; public PortalService(UserRepository u,TicketRepository t,TicketMessageRepository m,PasswordEncoder e,AiSuggestionService a){users=u;tickets=t;messages=m;encoder=e;ai=a;} public User current(){String email=(String)SecurityContextHolder.getContext().getAuthentication().getPrincipal();return users.findByEmailIgnoreCase(email).orElseThrow(()->new NotFound("User not found"));} public User register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new Conflict("Email is already registered");User u=new User();u.setFullName(r.fullName());u.setEmail(r.email().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));return users.save(u);} public boolean valid(String email,String pass){return users.findByEmailIgnoreCase(email).map(u->encoder.matches(pass,u.getPasswordHash())).orElse(false);} public User byEmail(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new NotFound("User not found"));} public Ticket ticket(Long id){return tickets.findByIdAndUserId(id,current().getId()).orElseThrow(()->new NotFound("Ticket not found"));} public Ticket create(TicketRequest r){Ticket t=new Ticket();t.setUser(current());t.setTitle(r.title());t.setDescription(r.description());t.setCategory(r.category());t.setPriority(r.priority());return tickets.save(t);} public List<Ticket> all(){return tickets.findAllByUserIdOrderByUpdatedAtDesc(current().getId());} public Ticket update(Long id,TicketUpdate r){Ticket t=ticket(id);if(r.title()!=null)t.setTitle(r.title());if(r.description()!=null)t.setDescription(r.description());if(r.category()!=null)t.setCategory(r.category());if(r.priority()!=null)t.setPriority(r.priority());if(r.status()!=null)t.setStatus(r.status());return tickets.save(t);} public void delete(Long id){tickets.delete(ticket(id));} public List<TicketMessage> messages(Long id){ticket(id);return messages.findAllByTicketIdOrderByCreatedAtAsc(id);} public TicketMessage message(Long id,MessageRequest r){TicketMessage m=new TicketMessage();m.setTicket(ticket(id));m.setUser(current());m.setMessage(r.message());return messages.save(m);} public String suggestion(Long id){return ai.suggest(ticket(id));}
 public User updateProfile(String fullName){User u=current();u.setFullName(fullName);return users.save(u);} public TicketResponse dto(Ticket t){return new TicketResponse(t.getId(),t.getTitle(),t.getDescription(),t.getCategory().name(),t.getPriority().name(),t.getStatus().name(),t.getCreatedAt(),t.getUpdatedAt());} public UserResponse user(User u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail());} public MessageResponse dto(TicketMessage m){return new MessageResponse(m.getId(),m.getMessage(),m.getUser().getId(),m.getCreatedAt());}}
